from lib import *
S = SS('f118')
R = J('f118'); P = R['paths']; aj, nd, ar = P['一次性 jsonify'], P['流式 NDJSON'], P['流式 JSON 数组']; vd = R['valid']
steps = [
    step(f"50 万行(约 {aj['mb']:.0f} MB JSON,真实 gunicorn gthread、PostgreSQL),每种方式各用一个全新的 worker:一次性 jsonify:响应头到达 {aj['ttfb']:.0f} ms(整个 JSON 生成完才发),全部读完 {aj['total']:.0f} ms,有 Content-Length,worker 峰值 RSS {aj['rss']:.0f} MB(空闲 {aj['base']:.0f} MB,多 {aj['rss'] - aj['base']:.0f} MB);流式 NDJSON(stream_with_context + 服务端游标 stream_results=True):响应头 {nd['ttfb']:.0f} ms、首块数据 {nd['first']:.0f} ms,全部读完 {nd['total']:.0f} ms,Transfer-Encoding: chunked(没有 Content-Length),峰值 RSS 仅比空闲多约 {nd['rss'] - nd['base']:.0f} MB;流式 JSON 数组:响应头 {ar['ttfb']:.0f} ms、首块 {ar['first']:.0f} ms,总时间 {ar['total']:.0f} ms,内存同样几乎不增。流式把内存从「随数据量增长」变成「恒定」,首字节更早,代价是总时间更长({nd['total'] / aj['total']:.1f} 倍,每行一次 yield 与 dumps)。", b=bars([['一次性 峰值内存增量', aj['rss'] - aj['base'], f"{aj['rss'] - aj['base']:.0f} MB"], ['流式 峰值内存增量', max(nd['rss'] - nd['base'], 1), f"{nd['rss'] - nd['base']:.0f} MB"]], aj['rss'] - aj['base'], mark=[0], done=[1]), t=tl(S(1)), done=lidx(S(1), '流式 NDJSON', '流式 JSON 数组'), mark=lidx(S(1), '一次性'), kv=KV([['一次性', f"首字节 {aj['ttfb']:.0f} ms,内存 +{aj['rss'] - aj['base']:.0f} MB"], ['流式', f"首块 {nd['first']:.0f} ms,内存 +{nd['rss'] - nd['base']:.0f} MB"], ['总时间', f"流式 {nd['total'] / 1000:.1f} s 对 {aj['total'] / 1000:.1f} s"]], ['流式'])),
    step(f"流式 JSON 数组(先 yield \"[\",逐行 yield 并在行间补逗号,最后 yield \"]\")读完后是合法 JSON:json.loads 解析成功,{vd[0]} 个元素,第一个 id 是 1、最后一个 id 是 500000。逗号要自己管理(第一个元素前不加)。NDJSON(每行一个 JSON 对象)不需要处理逗号,客户端也可以边读边解析。", t=tl(S(2)), done=lidx(S(2), 'json.loads'), kv=KV([['JSON 数组', '自己加 [ , ]'], ['NDJSON', '每行一个对象,更好流式处理']], ['NDJSON'])),
    step("流到一半出错:生成器在第 50000 个元素抛异常。响应头已经发出,状态码已经是 200,Transfer-Encoding: chunked;客户端读取时抛出 IncompleteRead(连接在分块没有正常结束时被断开),拿不到完整的 JSON。流式响应出错时没有办法再改状态码,客户端只能靠连接异常和不完整的内容发现问题;要在协议里留出结束标记(NDJSON 的最后一行或尾部的 summary 行),才能让客户端确认「完整收到」。", t=tl(S(3)), mark=lidx(S(3), 'IncompleteRead'), done=lidx(S(3), '状态码'), kv=KV([['状态码', '已经是 200,改不了'], ['客户端看到', 'IncompleteRead,内容不完整']], ['客户端看到'])),
    step("客户端中途断开(读了一点数据就关闭连接):服务端的生成器收到 GeneratorExit,日志依次是「generator closed (client went away)」「generator finally」,finally 里的清理(关闭数据库连接、游标)会执行。所以流式生成器里用 with 或 try/finally 管理资源,断线时才不会泄漏。", t=tl(S(4)), done=lidx(S(4), '服务端日志'), kv=KV([['客户端断开', '生成器收到 GeneratorExit'], ['finally', '仍会执行,可以释放资源']], ['finally'])),
]
A = mkartf('f118', 118, 'Flask,流式响应,NDJSON,stream_with_context,真实验证,动画演示',
    f'在 50 万行 PostgreSQL 数据上实测流式 JSON:一次性 jsonify 首字节 {aj["ttfb"]:.0f} ms、内存多 {aj["rss"] - aj["base"]:.0f} MB,流式首块 {nd["first"]:.0f} ms、内存只多约 {nd["rss"] - nd["base"]:.0f} MB 但总时间 {nd["total"] / aj["total"]:.1f} 倍;流式 JSON 数组合法性;流到一半出错时状态码已是 200、客户端 IncompleteRead;客户端断开时生成器收到 GeneratorExit。',
    '返回几十万行数据,是一次性 jsonify 还是流式?流式能省多少内存、慢多少?流到一半出错客户端怎么知道?客户端断开会怎样?这篇用真实的 gunicorn 与 PostgreSQL 服务端游标,把答案逐项量出来。',
    [(f'+{aj["rss"] - aj["base"]:.0f} → +{nd["rss"] - nd["base"]:.0f} MB', '返回 50 万行时 worker 峰值内存的增量:一次性与流式'), (f'{aj["ttfb"]:.0f} → {nd["ttfb"]:.0f} ms', '响应头到达时间:一次性与流式 NDJSON'), ('IncompleteRead', '流到一半出错时客户端读取到的异常')],
    [('一次性与流式', '<p>上一篇:<a href="flask-large-json-response.html">大批量 JSON 响应</a>;下一篇:<a href="flask-secret-key-usage.html">SECRET_KEY 的用途</a>。</p><p>每种方式单独起一个 worker:第一次我在同一个 worker 里连续测,上一次请求留下的内存把后面的峰值抬高了,结果不可信;而且我第一次忘了给生成器加 stream_with_context,流式路径返回了一个 141 字节的错误页,我是看到这个异常小的响应才发现的。</p>'), ('JSON 数组的合法性', None), ('出错与不完整', None), ('客户端断开', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口)、gunicorn gthread worker,内存取 ps 的 RSS 每 50 ms 采样的最大值', '没有验证:经过 nginx 反向代理时的缓冲(proxy_buffering 会让流式失效,见部署部分)、浏览器端边收边解析、gzip 与分块传输一起使用、HTTP/2 下的行为、超长流的超时设置(--timeout 对流式响应的影响)'], '流式 JSON', panels=[('t', 'term', '实验输出'), ('b', 'bars', '内存增量'), ('kv', 'kv', '要点')])
